package com.game_manager.gm.customer.crm;import java.time.Instant;import java.util.*;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
interface CustomerCrmNoteRepository extends JpaRepository<CustomerCrmNote,UUID>{@Query("select n from CustomerCrmNote n where n.profile.id=:profile and (:search is null or lower(n.body) like lower(concat('%',:search,'%'))) order by n.createdAt desc")List<CustomerCrmNote> search(@Param("profile")UUID profile,@Param("search")String search,Pageable page);long deleteByExpiresAtBefore(Instant cutoff);}
